import{_ as o,o as t,c as a,a0 as r}from"./chunks/framework.CNDWyMYS.js";const m=JSON.parse('{"title":"Platform overrides","description":"","frontmatter":{},"headers":[],"relativePath":"platform_overrides.md","filePath":"platform_overrides.md"}'),l={name:"platform_overrides.md"};function i(s,e,d,n,c,f){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="platform-overrides" tabindex="-1">Platform overrides <a class="header-anchor" href="#platform-overrides" aria-label="Permalink to &quot;Platform overrides&quot;">​</a></h1><p>To specify platform-specific information in rockspecs, one should use the <code>platforms</code> field of top-level tables.</p><p>In top-level tables, a field <code>platforms</code> is treated specially. If present, it may contain a table containing sub-tables representing different platforms. For example, <code>build.platforms.unix</code>, if present, as the name implies, would be a table containing specifics for building on Unix systems.</p><p>The contents of platform tables override the contents of the top-level table where <code>platforms</code> is located. For example, in a Linux system, an entry <code>build.platforms.linux.foo</code> will override <code>build.foo</code>. Tables are scanned deeply, so if <code>build.foo</code> is a table, the contents of <code>build.platforms.linux.foo</code> will add to or replace the contents of <code>build.foo</code>, instead of just replacing the entire table. Therefore, you don&#39;t need to rewrite the entire <code>build</code> section in a platform table, only the fields should change.</p>',4)])])}const u=o(l,[["render",i]]);export{m as __pageData,u as default};
